//
// fx_delaym.cpp - ADELdelay MONO: the delay engine with a single delay line (adel/adeldelaym_dsp.hpp, generated by make_mono_delay.py).
// For the mono lanes: mono input, mono output (L and R identical), half the cost; no Ping-Pong, R Time or Tap Spread.
//
#include "fx.h"
#include "adeldelaym_map.hpp"

class CAdelDelayM : public CFx
{
public:
	CAdelDelayM (float fRate)
	{
		m_Eng.init ((double) fRate);
	}

	unsigned Type (void) const { return FxAdelDelayM; }

	void Process (float *pL, float *pR, unsigned n, int *pMono, const float *pP)
	{
		// the excluded controls go back to the default values; the map goes from the block's index to that of the full specification
		const unsigned nFull = sizeof g_adeldelay_Params / sizeof g_adeldelay_Params[0];
		const unsigned nMono = sizeof g_adeldelaym_Map / sizeof g_adeldelaym_Map[0];
		float v[FX_MAX_P];
		for (unsigned i = 0; i < nFull; i++)
		{
			v[i] = g_adeldelay_Params[i].Def;
		}
		for (unsigned j = 0; j < nMono; j++)
		{
			v[g_adeldelaym_Map[j]] = pP[j];
		}
		for (unsigned j = 0; j < n; j++)
		{
			m_fIn[j] = *pMono ? pL[j] : 0.5f * (pL[j] + pR[j]);
		}
		m_Eng.process (m_fIn, pL, n, paramsFromControlsM (v));
		for (unsigned j = 0; j < n; j++)
		{
			pR[j] = pL[j];
		}
		*pMono = 1;
	}

private:
	adeldelaym::Delay m_Eng;
	float m_fIn[PL_MAX_BLOCK];
};

CFx *NewAdelDelayM (float fRate)
{
	return new CAdelDelayM (fRate);
}
